export const getCreateResultUrl = () => {




  return `/api/results`
}

/**
 * @summary Record a result and process downstream workflows
 */
export const createResult = async (resultInput: ResultInput, options?: Parameters<typeof customFetch>[1]): Promise<LabResult> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<LabResult>(getCreateResultUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(resultInput)
  }
);}





export const getCreateResultMutationKey = () => ['createResult'] as const;

export const getCreateResultMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createResult>>, TError,CreateResultMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createResult>>, TError,CreateResultMutationVariables, TContext> => {

const mutationKey = getCreateResultMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createResult>>, CreateResultMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  createResult(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateResultMutationResult = NonNullable<Awaited<ReturnType<typeof createResult>>>
    export type CreateResultMutationBody = BodyType<ResultInput>
    export type CreateResultMutationError = ErrorType<unknown>
    export type CreateResultMutationVariables = {data: BodyType<ResultInput>}

    /**
 * @summary Record a result and process downstream workflows
 */
export const useCreateResult = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createResult>>, TError,CreateResultMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createResult>>,
        TError,
        CreateResultMutationVariables,
        TContext
      > => {
      return useMutation(getCreateResultMutationOptions(options));
    }

